'use strict';

shared.IS_AUTO_RESOLUTION = true;
shared.IS_ASPECT_RATIO_LOCKED = false;

shared.LINES_AMPLITUDE = 10;

// resolution/properties change detection
shared.RESOLUTION_VERSION = -1;

shared.RESOLUTION_REFERENCE = new Vec2(2560, 1440);
shared.RESOLUTION_REFERENCE_HALF = new Vec2(shared.RESOLUTION_REFERENCE.x * 0.5, shared.RESOLUTION_REFERENCE.y * 0.5);

// resolution set by user if they want to disable autoresolution
shared.RESOLUTION_FIXED = new Vec2(shared.RESOLUTION_REFERENCE.x, shared.RESOLUTION_REFERENCE.y);
shared.RESOLUTION_FIXED_HALF = new Vec2(shared.RESOLUTION_FIXED.x * 0.5, shared.RESOLUTION_FIXED.y * 0.5);

shared.RESOLUTION_REAL = new Vec2(0, 0);
shared.RESOLUTION_REAL_HALF = new Vec2(0, 0);

shared.POSITION_OFFSET = new Vec2(0, 0);

function updateResolutionData(resolution) {
	// actual output area
	shared.RESOLUTION_REAL = shared.copyVec2(engine.screenResolution);
	shared.RESOLUTION_REAL_HALF = new Vec2(
		shared.RESOLUTION_REAL.x * 0.5,
		shared.RESOLUTION_REAL.y * 0.5
	);

	// layout area
	shared.RESOLUTION = shared.copyVec2(resolution);

	if (shared.IS_ASPECT_RATIO_LOCKED) {
		shared.RESOLUTION.x = Math.round(shared.RESOLUTION.y * shared.ASPECT_RATIO);

		// const realAspect = shared.RESOLUTION_REAL.x / shared.RESOLUTION_REAL.y;
		// const targetAspect = shared.ASPECT_RATIO;

		// if (targetAspect < realAspect) {
		// 	// target is narrower than output: pillarbox left/right
		// 	shared.RESOLUTION.x = Math.round(shared.RESOLUTION_REAL.y * targetAspect);
		// 	shared.RESOLUTION.y = shared.RESOLUTION_REAL.y;
		// }
		// else {
		// 	// target is wider than output: letterbox top/bottom
		// 	shared.RESOLUTION.x = shared.RESOLUTION_REAL.x;
		// 	shared.RESOLUTION.y = Math.round(shared.RESOLUTION_REAL.x / targetAspect);
		// }
	}

	shared.RESOLUTION_HALF = new Vec2(
		shared.RESOLUTION.x * 0.5,
		shared.RESOLUTION.y * 0.5
	);

	shared.SCALE_FACTOR = new Vec2(
		shared.RESOLUTION.x / shared.RESOLUTION_REFERENCE.x,
		shared.RESOLUTION.y / shared.RESOLUTION_REFERENCE.y
	);

	shared.UI_SCALE = Math.min(
		shared.SCALE_FACTOR.x,
		shared.SCALE_FACTOR.y
	);

	shared.UI_SCALE_SAFE = Math.max(
		shared.UI_SCALE,
		0.000001
	);

	shared.UI_SCALE_INVERSE = 1.0 / shared.UI_SCALE_SAFE;

	// offset of the aspect-corrected layout area inside the real output area
	shared.POSITION_OFFSET = new Vec2(
		(shared.RESOLUTION_REAL.x - shared.RESOLUTION.x) * 0.5,
		(shared.RESOLUTION_REAL.y - shared.RESOLUTION.y) * 0.5
	);

	shared.RESOLUTION_VERSION += 1;
}

shared.debugValueToString = (value) => {
	if (value === null) {
		return "null";
	}

	if (value === undefined) {
		return "undefined";
	}

	if (typeof value === "boolean" || typeof value === "number" || typeof value === "string") {
		return String(value);
	}

	// Vec-like objects
	if (typeof value === "object" && value.x !== undefined && value.y !== undefined) {
		return value.x + "x" + value.y;
	}
	if (typeof value === "object" && value.x !== undefined && value.y !== undefined && value.z !== undefined) {
		return value.x + "x" + value.y + "x" + value.z;
	}

	// user property-like objects
	if (typeof value === "object" && value.value !== undefined) {
		return shared.debugValueToString(value.value);
	}

	try {
		return JSON.stringify(value);
	}
	catch (e) {
		return String(value);
	}
}

shared.terminalPrint = (tag, ...args) => {
	let message = "\n[machine-core debug] " + tag;

	for (let i = 0; i < args.length; i += 2) {
		const name = args[i];
		const value = args[i + 1];

		message += "\n" + name + ": " + shared.debugValueToString(value);
	}

	throw new Error(message);
}

export function applyUserProperties(properties) {
	if (properties.hasOwnProperty('autoresolution')) {
		shared.IS_AUTO_RESOLUTION = properties.autoresolution;
	}

	if (properties.hasOwnProperty('aspectratio')) {
		shared.IS_ASPECT_RATIO_LOCKED = Number(properties.aspectratio) != 0;
		shared.ASPECT_RATIO = Number(properties.aspectratio);
	}

	if (properties.hasOwnProperty('resolutionx')) {
		shared.RESOLUTION_FIXED.x = Number(properties.resolutionx);
		shared.RESOLUTION_FIXED_HALF.x = Number(properties.resolutionx * 0.5);
	}
	if (properties.hasOwnProperty('resolutiony')) {
		shared.RESOLUTION_FIXED.y = Number(properties.resolutiony);
		shared.RESOLUTION_FIXED_HALF.y = Number(properties.resolutiony * 0.5);
	}

	if (shared.IS_AUTO_RESOLUTION) {
		updateResolutionData(engine.screenResolution);
	}
	else {
		updateResolutionData(shared.RESOLUTION_FIXED);
	}
}

/**
 * @param {Number} value - screen resolution
 */
export function resizeScreen(value) {
	if (shared.IS_AUTO_RESOLUTION) {
		updateResolutionData(value);
	} else {
		updateResolutionData(shared.RESOLUTION_FIXED);
	}
}

/**
 * @param {Number} value - for property 'visible'
 * @return {Number} - update current property value
 */
export function init(value) {
	if (shared.IS_AUTO_RESOLUTION) {
		updateResolutionData(engine.screenResolution);
	} else {
		updateResolutionData(shared.RESOLUTION_FIXED);
	}
}

shared.copyVec2 = (value) => {
	return new Vec2(
		Number(value.x) || 0,
		Number(value.y) || 0
	);
};

shared.copyVec3 = (value) => {
	return new Vec3(
		Number(value.x) || 0,
		Number(value.y) || 0,
		Number(value.z) || 0
	);
};

shared.clamp = (num, min, max) => {
	return Math.min(Math.max(num, min), max);
};

shared.getPosition = (origin) => {
	return new Vec2(
		origin.x * shared.SCALE_FACTOR.x,
		origin.y * shared.SCALE_FACTOR.y
	);
}

shared.getPositionTopLeft = () => {
	return new Vec2(
		-shared.RESOLUTION_HALF.x,
		shared.RESOLUTION_HALF.y
	);
}

shared.getPositionCenterLeft = () => {
	return new Vec2(
		-shared.RESOLUTION_HALF.x,
		0
	);
}

shared.getPositionBottomLeft = () => {
	return new Vec2(
		-shared.RESOLUTION_HALF.x,
		-shared.RESOLUTION_HALF.y
	);
}

shared.getPositionTopCenter = () => {
	return new Vec2(
		0,
		shared.RESOLUTION_HALF.y
	);
}

shared.getPositionCenter = () => {
	return new Vec2(
		0,
		0
	);
}

shared.getPositionBottomCenter = () => {
	return new Vec2(
		0,
		-shared.RESOLUTION_HALF.y
	);
}

shared.getPositionTopRight = () => {
	return new Vec2(
		shared.RESOLUTION_HALF.x,
		shared.RESOLUTION_HALF.y
	);
}

shared.getPositionCenterRight = () => {
	return new Vec2(
		shared.RESOLUTION_HALF.x,
		0
	);
}

shared.getPositionBottomRight = () => {
	return new Vec2(
		shared.RESOLUTION_HALF.x,
		-shared.RESOLUTION_HALF.y
	);
}

shared.getScaleX = (scale) => {
	return scale.x * shared.SCALE_FACTOR.x;
}

shared.getScaleY = (scale) => {
	return scale.y * shared.SCALE_FACTOR.y;
}

shared.getScale = (scale) => {
	return new Vec2(
		scale.x * shared.SCALE_FACTOR.x,
		scale.y * shared.SCALE_FACTOR.y
	);
}

shared.getScaleMin = (scale) => {
	let factor = Math.min(shared.SCALE_FACTOR.x, shared.SCALE_FACTOR.y);
	return new Vec2(
		scale.x * factor,
		scale.y * factor
	);
}

shared.getScaleMax = (scale) => {
	let factor = Math.max(shared.SCALE_FACTOR.x, shared.SCALE_FACTOR.y);
	return new Vec2(
		scale.x * factor,
		scale.y * factor
	);
}

shared.getScaleBackground = (backgroundResolution) => {
	if (shared.IS_AUTO_RESOLUTION) {
		return new Vec2(
			shared.RESOLUTION_REAL.x / backgroundResolution.x,
			shared.RESOLUTION_REAL.y / backgroundResolution.y
		);
	}
	else {
		return new Vec2(
			shared.RESOLUTION_FIXED.x / backgroundResolution.x,
			shared.RESOLUTION_FIXED.y / backgroundResolution.y
		);
	}
}

shared.getScaleUi = (scale) => {
	return new Vec2(
		scale.x * shared.UI_SCALE,
		scale.y * shared.UI_SCALE
	);
};

shared.getScaleUiInversed = () => {
	return shared.UI_SCALE_INVERSE;
};

shared.getFontSize = (size) => {
	return Math.round(size * shared.UI_SCALE * 100) / 100;
};

