let isOffsetChanged = true;

let resolutionVersion = -1;

let origin = new Vec2();
let offset = new Vec2();


export function applyUserProperties(properties) {
	if (properties.hasOwnProperty('titlexoffset')) {
		offset.x = properties.titlexoffset;
		isOffsetChanged = true;
	}
	if (properties.hasOwnProperty('titleyoffset')) {
		offset.y = properties.titleyoffset;
		isOffsetChanged = true;
	}
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function init(value) {
	origin = shared.copyVec3(value);
	return value;
}

/**
 * @param {Vec3} value - for property 'origin'
 * @return {Vec3} - update current property value
 */
export function update(value) {
	if (resolutionVersion !== shared.RESOLUTION_VERSION || isOffsetChanged) {
resolutionVersion = shared.RESOLUTION_VERSION;
		isOffsetChanged = false;

		let newOrigin = shared.getPosition(new Vec2(origin.x + offset.x, origin.y + offset.y));
		value.x = newOrigin.x;
		value.y = newOrigin.y;
	}

	return value;
}

