alpha.script:
'use strict';

let isBlinkingEnabled = true;


export function applyUserProperties(properties) {
	if (properties.hasOwnProperty('timebarblinking')) {
		isBlinkingEnabled = Boolean(properties.timebarblinking);
	}
}

/**
 * @param {Number} value - for property 'alpha'
 * @return {Number} - update current property value
 */
export function update(value) {
	if (!isBlinkingEnabled) {
		return value;
	}

	let delta = Math.sin(engine.runtime * 4) * 0.3 + 1.05;

	return shared.clamp(delta, 0.8, 1);
}

